.version 8.0
.target sm_89
.address_size 64
.visible .entry conv2d_kernel(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 output_ptr
)
{
    .reg .s32 %r<66>;
    .reg .s64 %rd<20>;
    .reg .f32 %f<10>;
    .reg .pred %p<16>;
    .shared .align 4 .b8 smem_weight[5760];
    ld.param.u64 %rd1, [input_ptr];
    ld.param.u64 %rd2, [weight_ptr];
    ld.param.u64 %rd3, [output_ptr];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    mov.u32 %r1, %ctaid.x;   // group = n*64+oc
    mov.u32 %r2, %ntid.x;
    mov.u32 %r3, %tid.x;
    mov.u32 %r4, %ctaid.y;   // spatial tile index
    mov.u32 %r10, 64;
    div.s32 %r5, %r1, %r10;    // n
    rem.s32 %r6, %r1, %r10;    // oc
    // cooperative load of weight slice for this oc into shared memory
    mov.u32 %r11, 1440;
    mul.lo.s32 %r12, %r6, 1440;   // oc*1440 (base index in global weight)
    mov.u32 %r13, %r3;            // loop index = tid
LOAD_LOOP:
    setp.ge.s32 %p1, %r13, %r11;
    @%p1 bra LOAD_DONE;
    add.s32 %r14, %r12, %r13;      // global weight index
    cvt.s64.s32 %rd10, %r14;
    mul.lo.s64 %rd10, %rd10, 4;
    add.s64 %rd11, %rd2, %rd10;
    ld.global.f32 %f1, [%rd11];
    mul.lo.s32 %r15, %r13, 4;      // byte offset in shared mem
    mov.u32 %r16, smem_weight;
    add.s32 %r17, %r16, %r15;
    st.shared.f32 [%r17], %f1;
    add.s32 %r13, %r13, %r2;
    bra LOAD_LOOP;
LOAD_DONE:
    bar.sync 0;
    // paired spatial index (register blocking: compute 2 adjacent output columns per thread)
    mad.lo.s32 %r20, %r4, %r2, %r3;   // pair_idx = ctaid.y*ntid.x+tid.x
    mov.u32 %r21, 125984;
    setp.ge.s32 %p2, %r20, %r21;
    @%p2 bra DONE;
    mul.lo.s32 %r20, %r20, 2;         // idx2 = pair_idx*2
    mov.u32 %r22, 496;
    div.s32 %r23, %r20, %r22;         // oh
    rem.s32 %r24, %r20, %r22;         // ow (first column)
    add.s32 %r25, %r24, 1;            // ow2 (second column)
    mov.f32 %f2, 0f00000000;          // accumulator for ow
    mov.f32 %f5, 0f00000000;          // accumulator for ow2
    mov.u32 %r30, 0;
