    setp.ge.s32 %p4, %r31, 5;
    @%p4 bra KH_DONE;
    mul.lo.s32 %r32, %r31, 2;
    add.s32 %r33, %r23, %r32;
    sub.s32 %r33, %r33, 2;            // ih
    setp.lt.s32 %p5, %r33, 0;
    setp.ge.s32 %p6, %r33, 512;
    or.pred %p7, %p5, %p6;
    @%p7 bra KH_CONTINUE;
    mul.lo.s32 %r37, %r5, 8388608;    // n*8388608 (hoisted, shared by both columns)
    mul.lo.s32 %r38, %r30, 262144;    // ic*262144
    add.s32 %r39, %r37, %r38;
    mul.lo.s32 %r40, %r33, 512;       // ih*512
    add.s32 %r39, %r39, %r40;         // base = n*8388608+ic*262144+ih*512
    mov.u32 %r34, 0;
