    setp.ge.s32 %p8, %r34, 9;
    @%p8 bra KW_DONE;
    mul.lo.s32 %r35, %r34, 3;
    add.s32 %r36, %r24, %r35;
    sub.s32 %r36, %r36, 4;            // iw for ow
    add.s32 %r60, %r36, 1;            // iw for ow2 (=iw+1)
    setp.lt.s32 %p9, %r36, 0;
    setp.ge.s32 %p10, %r36, 512;
