    setp.lt.s32 %p12, %r60, 0;
    setp.ge.s32 %p13, %r60, 512;
    or.pred %p14, %p12, %p13;         // invalid flag for second column
    // weight fetch from shared memory: reused across both output columns
    mul.lo.s32 %r41, %r30, 45;
    mul.lo.s32 %r42, %r31, 9;
    add.s32 %r43, %r41, %r42;
    add.s32 %r43, %r43, %r34;
    mul.lo.s32 %r44, %r43, 4;
    mov.u32 %r45, smem_weight;
    add.s32 %r46, %r45, %r44;
    ld.shared.f32 %f4, [%r46];
    @%p11 bra SKIP1;
    add.s32 %r62, %r39, %r36;         // addr index for ow
    cvt.s64.s32 %rd12, %r62;
    mul.lo.s64 %rd12, %rd12, 4;
    add.s64 %rd13, %rd1, %rd12;
    ld.global.f32 %f3, [%rd13];
    fma.rn.f32 %f2, %f3, %f4, %f2;
SKIP1:
    @%p14 bra SKIP2;
    add.s32 %r63, %r39, %r60;         // addr index for ow2
    cvt.s64.s32 %rd18, %r63;
    mul.lo.s64 %rd18, %rd18, 4;
    add.s64 %rd19, %rd1, %rd18;
    ld.global.f32 %f6, [%rd19];
    fma.rn.f32 %f5, %f6, %f4, %f5;
SKIP2:
    add.s32 %r34, %r34, 1;
    bra KW_LOOP;
KW_DONE:
KH_CONTINUE:
    add.s32 %r31, %r31, 1;
    bra KH_LOOP;
KH_DONE:
    add.s32 %r30, %r30, 1;
    bra IC_LOOP;
IC_DONE:
    mul.lo.s32 %r50, %r5, 16125952;
    mul.lo.s32 %r51, %r6, 251968;
    add.s32 %r52, %r50, %r51;
    mul.lo.s32 %r53, %r23, 496;
    add.s32 %r54, %r52, %r53;
    add.s32 %r55, %r54, %r24;         // final flat index for ow
    add.s32 %r56, %r54, %r25;         // final flat index for ow2
    cvt.s64.s32 %rd14, %r55;
    mul.lo.s64 %rd14, %rd14, 4;
    add.s64 %rd15, %rd3, %rd14;
    st.global.f32 [%rd15], %f2;
    cvt.s64.s32 %rd16, %r56;
    mul.lo.s64 %rd16, %rd16, 4;
    add.s64 %rd17, %rd3, %rd16;
    st.global.f32 [%rd17], %f5;
DONE:
    ret;
}
"""

_ptx_module = None


def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module


def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_kernel")


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1),
                 bias: bool = False):
        super().__init__()
        self.conv2d = nn.Conv2d(in_channels, out_channels, kernel_size,
                                 stride=stride, padding=padding,
                                 dilation=dilation, bias=bias)
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        N, C, H, W = x.shape
        kH, kW = self.kernel_size
        padH, padW = self.padding
        dilH, dilW = self.dilation
        strideH = strideW = self.stride

