        grid_y = (pairs + block_size - 1) // block_size
        module = _get_ptx_module()
        module.launch(
            "conv2d_kernel",
            grid=(grid_x, grid_y, 1),
            block=(block_size, 1, 1),
            arguments=[x, weight, output],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
